def corrige_status_paas_retificados(apps, schema_editor):
    """
    PAAs que concluíram a retificação (documento final + ata de retificação concluídos)
    mas permaneceram com status GERADO passam para RETIFICADO.

    O update via queryset não dispara os signals do auditlog, então cada alteração
    é registrada manualmente no Audit Log.
    """
    paa_model = apps.get_model("paa", "Paa")
    documento_paa_model = apps.get_model("paa", "DocumentoPaa")
    ata_paa_model = apps.get_model("paa", "AtaPaa")
    content_type_model = apps.get_model("contenttypes", "ContentType")
    log_entry_model = apps.get_model("auditlog", "LogEntry")

    doc_final_retificacao = documento_paa_model.objects.filter(
        paa=OuterRef("pk"),
        versao=DocumentoPaa.VersaoChoices.FINAL,
        retificacao=True,
        status_geracao=DocumentoPaa.StatusChoices.CONCLUIDO,
    )

    ata_retificacao = ata_paa_model.objects.filter(
        paa=OuterRef("pk"),
        tipo_ata=AtaPaa.ATA_RETIFICACAO,
        status_geracao_pdf=AtaPaa.STATUS_CONCLUIDO,
        pdf_gerado_previamente=True,
    )

    paas_gerados = list(
        paa_model.objects.filter(
            Exists(doc_final_retificacao),
            Exists(ata_retificacao),
            status=PaaStatusEnum.GERADO.name,
        ).select_related("periodo_paa", "associacao")
    )

    if not paas_gerados:
        return

    content_type, _ = content_type_model.objects.get_or_create(app_label="paa", model="paa")
    changes = json.dumps({"status": [PaaStatusEnum.GERADO.name, PaaStatusEnum.RETIFICADO.name]})

    logs = [
        log_entry_model(
            content_type=content_type,
            object_pk=str(paa.pk),
            object_id=paa.pk,
            object_repr=f'{paa.periodo_paa} - {paa.associacao}',
            action=LogEntry.Action.UPDATE,
            changes=changes,
            additional_data={"motivo": MOTIVO_CORRECAO, "paa_uuid": str(paa.uuid)},
        )
        for paa in paas_gerados
    ]

    paa_model.objects.filter(pk__in=[paa.pk for paa in paas_gerados]).update(status=PaaStatusEnum.RETIFICADO.name)
    log_entry_model.objects.bulk_create(logs)


